const tasks = $input.first().json.tasks || [];
const STAGE = {
  lead: 'lead',
  qualified: 'qualified',
  'discovery set': 'discovery_set',
  'discovery done': 'discovery_done',
  'ambition set': 'ambition_set',
  'ambition done': 'ambition_done',
  'architect set': 'architect_set',
  'architect done': 'architect_done',
  enrolled: 'enrolled',
  dropped: 'dropped'
};
return tasks.map(t => {
  const status = (t.status && t.status.status || '').toLowerCase();
  return {
    json: {
      clickup_task_id: t.id,
      created_at: new Date(Number(t.date_created)).toISOString(),
      parent_name: t.name,
      source: (t.custom_fields || []).find(f => f.name === 'Source')?.value || 'organic',
      campaign_id: (t.custom_fields || []).find(f => f.name === 'Campaign')?.value || null,
      creative_id: (t.custom_fields || []).find(f => f.name === 'Creative')?.value || null,
      is_qualified: ['qualified','discovery set','discovery done','ambition set','ambition done','architect set','architect done','enrolled'].includes(status),
      stage: STAGE[status] || 'lead',
      occurred_at: new Date(Number(t.date_updated)).toISOString()
    }
  };
});

parameters.query:
insert into lead_stage_events (lead_id, stage, occurred_at, actor)
select $1::uuid, $2, $3::timestamptz, 'n8n'
where not exists (
  select 1 from lead_stage_events
  where lead_id = $1::uuid and stage = $2 and occurred_at = $3::timestamptz
);
